test_that("native extraction maps only compatible fields", {bm<-dm<-matrix(c(.1,.2),2,1,dimnames=list(c("m1","m2"),"t1"));fit<-list(bm=bm,dm=dm,cov_g_mean=matrix(1,1,1,dimnames=list("t1","t1")),convergence=list(ok=TRUE),diagnostics=list(native=1),memory_estimate=list(bytes=8),component_probabilities=matrix(1),pi_mean=.2,annotation=list(alpha=1));r<-extract_sblr_result(list(native_fit=fit,elapsed_seconds=.5,warnings="w"),"native");expect_equal(r$estimates$effects,bm);expect_equal(r$estimates$pip,dm);expect_equal(r$estimates$genetic_covariance,fit$cov_g_mean);expect_equal(r$computation$elapsed_seconds,.5);expect_null(r$estimates$component_probabilities);expect_equal(r$native_fit$pi_mean,.2);expect_null(extract_sblr_result(fit,"native",keep_native_fit=FALSE)$native_fit)})
test_that("annotation adapter permits NULL method", {m<-new_sblr_native_method("annot","Annotation","stblr_csr_annot",NULL,"annotations");expect_null(m$metadata$method);expect_error(m$fit(list(a=1),list(a=2)),"Duplicated")})
